Fiq_Entry * fiq_entry_request (void)   // get link from free list or create one
{
  Fiq_Entry *free = fiq_free_list ;

  if (free != NULL) 
    {    
       fiq_free_list = free->next ;                
       return free ;                  
    }
  else
    {
      return ((Fiq_Entry *) os_mem_request (sizeof (Fiq_Entry))) ;
    }
}
//--------------------------------------------------------------------------//
void fiq_entry_release (Fiq_Entry * fiq_entry)
{
    fiq_entry->next = fiq_free_list ;   
    fiq_free_list = fiq_entry ;
}

